# Generated by SDD apply phase — data migration for Especialidad split

from django.db import migrations


def copy_especialidad_data(apps, schema_editor):
    """
    Copy data from old Especialidad to EspecialidadIngeniero and EspecialidadRevision.
    
    Mapeo de datos (del Excel obs #4682):
    
    EspecialidadIngeniero (6 registros):
      codigo | capitulo_id | nombre
      01     | 02         | ING. CIVIL
      01     | 09         | ING. SANITARIA
      02     | 05         | ING. MECÁNICO ELECTRICISTA
      04     | 15         | ING. ELECTRICISTA
      07     | 15         | ING. EN ELECTRICIDAD
      10     | 15         | ING. ELECTRICO
    
    EspecialidadRevision (3 registros):
      codigo | slug          | nombre
      01     | civil         | Ingeniería Civil
      02     | sanitaria     | Ingeniería Sanitaria  
      03     | electrica-mecanica | Eléctrica/Mecánica
    """
    EspecialidadIngeniero = apps.get_model("usuarios", "EspecialidadIngeniero")
    EspecialidadRevision = apps.get_model("usuarios", "EspecialidadRevision")
    PerfilIngeniero = apps.get_model("usuarios", "PerfilIngeniero")
    
    # Create EspecialidadIngeniero records
    especialidad_ingeniero_map = [
        # (codigo, capitulo_registro_id, nombre)
        ("01", "02", "ING. CIVIL"),
        ("01", "09", "ING. SANITARIA"),
        ("02", "05", "ING. MECÁNICO ELECTRICISTA"),
        ("04", "15", "ING. ELECTRICISTA"),
        ("07", "15", "ING. EN ELECTRICIDAD"),
        ("10", "15", "ING. ELECTRICO"),
    ]
    
    Capitulo = apps.get_model("usuarios", "Capitulo")
    
    created_esp_ingeniero = {}
    for codigo, capitulo_reg_id, nombre in especialidad_ingeniero_map:
        capitulo = Capitulo.objects.filter(registro_id=capitulo_reg_id).first()
        if capitulo:
            esp, created = EspecialidadIngeniero.objects.get_or_create(
                codigo=codigo,
                capitulo=capitulo,
                defaults={"nombre": nombre},
            )
            created_esp_ingeniero[(codigo, capitulo_reg_id)] = esp
            if created:
                print(f"  Created EspecialidadIngeniero: {codigo}/{capitulo_reg_id} -> {nombre}")
        else:
            print(f"  WARNING: Capitulo {capitulo_reg_id} not found for EspecialidadIngeniero {codigo}")
    
    # Create EspecialidadRevision records (3 registros fijos)
    especialidad_revision_map = [
        ("01", "civil", "Ingeniería Civil"),
        ("02", "sanitaria", "Ingeniería Sanitaria"),
        ("03", "electrica-mecanica", "Eléctrica/Mecánica"),
    ]
    
    created_esp_revision = {}
    for codigo, slug, nombre in especialidad_revision_map:
        esp_rev, created = EspecialidadRevision.objects.get_or_create(
            codigo=codigo,
            defaults={"slug": slug, "nombre": nombre},
        )
        created_esp_revision[codigo] = esp_rev
        if created:
            print(f"  Created EspecialidadRevision: {codigo} -> {nombre}")
    
    # Update PerfilIngeniero.especialidad FKs
    # NOTE: after migration 0003 ran, PerfilIngeniero.especialidad FK already points to
    # EspecialidadIngeniero (the new table). We cannot use perfil.especialidad to read
    # old Especialidad data — it would return None (new table is empty at this point).
    # Instead we read the old Especialidad row directly using the FK column value that
    # was stored before AlterField repointed the FK.
    old_especialidad_model = apps.get_model("usuarios", "Especialidad")
    
    updated_count = 0
    skipped_null = 0
    for perfil in PerfilIngeniero.objects.select_related("capitulo").all():
        old_esp_id = perfil.especialidad_id
        if old_esp_id is None:
            # FK was already NULL — nothing to repoint
            skipped_null += 1
            continue
        
        # Read the old Especialidad row directly from the DB
        try:
            old_esp = old_especialidad_model.objects.get(pk=old_esp_id)
        except Exception:
            # Record was already removed or invalid — leave FK NULL
            print(f"  WARNING: old Especialidad {old_esp_id} not found for PerfilIngeniero {perfil.cip}")
            continue
        
        old_codigo = old_esp.codigo
        capitulo_reg_id = perfil.capitulo.registro_id if perfil.capitulo else None
        
        key = (old_codigo, capitulo_reg_id)
        new_esp_ingeniero = None
        if key in created_esp_ingeniero:
            new_esp_ingeniero = created_esp_ingeniero[key]
        else:
            # Fallback: try just codigo match when capitulo is NULL or unmatched
            for (cod, cap_id), esp_ing in created_esp_ingeniero.items():
                if cod == old_codigo and cap_id is None:
                    new_esp_ingeniero = esp_ing
                    break
        
        if new_esp_ingeniero:
            perfil.especialidad = new_esp_ingeniero
            perfil.save(update_fields=["especialidad"])
            updated_count += 1
        else:
            print(f"  WARNING: Could not repoint PerfilIngeniero {perfil.cip} (old Especialidad {old_codigo}, capitulo {capitulo_reg_id})")
    
    print(f"  Updated {updated_count} PerfilIngeniero.especialidad FKs ({skipped_null} were already NULL)")


def reverse_migration(apps, schema_editor):
    """Reverse: not reversible since tables are split."""
    pass


class Migration(migrations.Migration):

    dependencies = [
        ("usuarios", "0003_especialidadrevision_especialidadingeniero_and_more"),
    ]

    operations = [
        migrations.RunPython(copy_especialidad_data, reverse_migration),
    ]
